import { Component, signal, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { Auth, signOut } from '@angular/fire/auth';
import { CircuitFormComponent } from '../circuit-form/circuit-form.component';
import { FatigueChartComponent } from '../fatigue-chart/fatigue-chart.component';
import { FatigueLocalEngineService } from '../../services/fatigue-local-engine.service';
import {
  ParametrosCircuito,
  PuntoFatiga,
  MetricasSimulacion
} from '../../models/punto-fatiga.model';
import { WorkoutService } from '../../services/workout.service';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, CircuitFormComponent, FatigueChartComponent],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent {
  datos = signal<PuntoFatiga[]>([]);
  metricas = signal<MetricasSimulacion | null>(null);
  cargando = signal(false);
  error = signal<string | null>(null);
  insightMessage = signal<{ texto: string; nivel: 'ok' | 'warn' | 'danger' } | null>(null);

  private auth = inject(Auth);
  private localEngine = inject(FatigueLocalEngineService);
  private workoutService = inject(WorkoutService);
  private router = inject(Router);

  get currentUser() {
    return this.auth.currentUser;
  }

  async cerrarSesion() {
    await signOut(this.auth);
    this.router.navigate(['/login']);
  }

  onSimular(params: ParametrosCircuito) {
    this.cargando.set(true);
    this.error.set(null);

    const r = this.localEngine.simular(params);
    this.datos.set(r.data);
    this.metricas.set(r.metricas);
    this.cargando.set(false);
    this.insightMessage.set(this.calcularInsight(r.metricas.fatigaMaxima));

    this.workoutService.guardarSimulacion({
      trabajoS: params.workDuration,
      descansoS: params.restDuration,
      rondas: params.rounds,
      intensidad: params.E0,
      kia_utilizado: params.kia,
      duracionTotalS: r.metricas.duracionTotal
    });
  }

  onReset() {
    this.datos.set([]);
    this.metricas.set(null);
    this.error.set(null);
    this.insightMessage.set(null);
  }

  private calcularInsight(fatigaMax: number): { texto: string; nivel: 'ok' | 'warn' | 'danger' } {
    if (fatigaMax > 150) {
      return {
        nivel: 'danger',
        texto: '⚠️ Atención: Entrarás en zona de fallo muscular. Recomendamos aumentar tu tiempo de descanso o reducir la intensidad.'
      };
    } else if (fatigaMax >= 100) {
      return {
        nivel: 'warn',
        texto: '🟡 Nivel de exigencia moderado-alto. Estás en zona de alto rendimiento, pero vigila tu fatiga técnica ronda a ronda.'
      };
    } else {
      return {
        nivel: 'ok',
        texto: '✅ Rendimiento óptimo y recuperación eficiente. Tu circuito está bien balanceado para sesiones de alta frecuencia.'
      };
    }
  }
}
