import { Injectable, inject } from '@angular/core';
import { Firestore, collection, addDoc } from '@angular/fire/firestore';
import { Auth } from '@angular/fire/auth';

@Injectable({ providedIn: 'root' })
export class WorkoutService {
  private db = inject(Firestore);
  private auth = inject(Auth);

  async guardarSimulacion(datosSimulacion: {
    trabajoS: number;
    descansoS: number;
    rondas: number;
    intensidad: number;
    kia_utilizado: number;
    duracionTotalS: number;
  }) {
    const user = this.auth.currentUser;
    if (!user) {
      console.warn('Usuario no autenticado, no se guardará el historial.');
      return;
    }

    try {
      const historialRef = collection(this.db, 'Usuarios', user.uid, 'HistorialEntrenamientos');
      await addDoc(historialRef, {
        ...datosSimulacion,
        fecha: new Date()
      });
    } catch (error) {
      console.error('Error al guardar simulación:', error);
    }
  }
}
