import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { Auth, GoogleAuthProvider, signInWithPopup } from '@angular/fire/auth';
import { ProfileService } from '../../services/profile.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="login-container">
      <div class="login-card">
        <div class="logo-mark">∂F/∂t</div>
        <h1>Motor Inteligente de Fatiga</h1>
        <p class="subtitle">Inicia sesión para comenzar a calcular y monitorear tus circuitos de entrenamiento.</p>

        <button class="btn-google" (click)="loginConGoogle()" [disabled]="loading">
          <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google Logo" class="google-icon">
          <span *ngIf="!loading">Iniciar sesión con Google</span>
          <span *ngIf="loading">Iniciando sesión...</span>
        </button>

        <p class="error-msg" *ngIf="error">{{ error }}</p>
      </div>
    </div>
  `,
  styles: [`
    .login-container {
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      background: var(--bg);
      padding: 20px;
    }
    .login-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 40px;
      width: 100%;
      max-width: 400px;
      text-align: center;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
    }
    .logo-mark {
      font-family: 'Cambria Math', 'STIX Two Math', serif;
      font-style: italic;
      font-size: 2.5rem;
      color: var(--accent);
      margin-bottom: 16px;
    }
    h1 {
      font-family: var(--font-display);
      font-size: 1.5rem;
      color: var(--text);
      margin-bottom: 8px;
    }
    .subtitle {
      font-family: var(--font-body);
      font-size: 0.9rem;
      color: var(--text-muted);
      margin-bottom: 32px;
      line-height: 1.5;
    }
    .btn-google {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 100%;
      gap: 12px;
      background: white;
      color: #3c4043;
      border: 1px solid #dadce0;
      padding: 12px 16px;
      border-radius: 4px;
      font-family: 'Roboto', sans-serif;
      font-weight: 500;
      font-size: 14px;
      cursor: pointer;
      transition: background-color 0.2s, box-shadow 0.2s;
    }
    .btn-google:hover:not(:disabled) {
      background: #f8f9fa;
      box-shadow: 0 1px 2px 0 rgba(60,64,67,0.30), 0 1px 3px 1px rgba(60,64,67,0.15);
    }
    .btn-google:disabled {
      opacity: 0.7;
      cursor: not-allowed;
    }
    .google-icon {
      width: 18px;
      height: 18px;
    }
    .error-msg {
      margin-top: 16px;
      color: var(--error, #ff4d4d);
      font-size: 0.85rem;
    }
  `]
})
export class LoginComponent {
  loading = false;
  error: string | null = null;

  private auth = inject(Auth);
  private router = inject(Router);
  private profileService = inject(ProfileService);

  async loginConGoogle() {
    this.loading = true;
    this.error = null;
    const provider = new GoogleAuthProvider();

    try {
      const result = await signInWithPopup(this.auth, provider);
      const user = result.user;

      const profileExists = await this.profileService.checkProfileExists(user.uid);

      if (profileExists) {
        this.router.navigate(['/']);
      } else {
        this.router.navigate(['/perfil']);
      }
    } catch (err: any) {
      console.error(err);
      this.error = 'Ocurrió un error al iniciar sesión. Inténtalo de nuevo.';
    } finally {
      this.loading = false;
    }
  }
}
